def max_product(num_str: str, N: int, K: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def dp(i, k):
        if i == N:
            return 1 if k == K else 0
        if k == K:
            return int(num_str[i:])
        return max(dp(i + 1, k), (int(num_str[i:i + j]) * dp(i + j, k - 1)) for j in range(1, N - i + 1))

    return dp(0, K)

